/// Creates a contract using the caller's client and signing configuration.
let bind (web3: Web3) (address: string) = web3.Eth.GetContract(abi, address)

/// Encodes supplied deployment bytecode and constructor arguments.
let encodeDeployment (web3: Web3) (bytecode: string) (args: ConstructorParams) =
    web3.Eth.DeployContract.GetData(bytecode, abi, [| box args.Owner; box args.Staking |])

let deploy (web3: Web3) (bytecode: string) (sender: string) (gas: HexBigInteger) (value: HexBigInteger) (args: ConstructorParams) =
    if not (isNull value) && value.Value <> BigInteger.Zero then invalidArg "value" "Constructor is not payable"
    web3.Eth.DeployContract.SendRequestAsync(abi, bytecode, sender, gas, value, [| box args.Owner; box args.Staking |])

