let decodeUpdateStakingAddressResult (data: string) : UpdateStakingAddressResult =
    Nethereum.ABI.FunctionEncoding.FunctionCallDecoder().DecodeFunctionOutput(Activator.CreateInstance<UpdateStakingAddressResult>(), data)

/// Sends through the client's configured transaction manager.
let sendUpdateStakingAddress (contract: Contract) (options: TransactionInput) (args: UpdateStakingAddressParams) =
    if isNull options then nullArg "options"
    if not (isNull options.Value) && options.Value.Value <> BigInteger.Zero then invalidArg "options" "Function is not payable"
    options.To <- contract.Address
    contract.GetFunctionBySignature("0x5b06a1d1").SendTransactionAsync(options, [| box args.Staking |])

