let decodeAccountGrantAssignedEvent (contract: Contract) (log: FilterLog) : AccountGrantAssignedEvent =
    let decoded = contract.GetEventBySignature("0x8069a87735a71ef98bd747a24e1502aeda0a0b31aef75137cb7b07fbc97716a4").DecodeAllEventsForEvent<AccountGrantAssignedEvent>([| log |])
    if decoded.Count <> 1 then invalidArg "log" "Log does not match event"
    decoded.[0].Event

let queryAccountGrantAssigned (contract: Contract) (filter: NewFilterInput) =
    if isNull filter || isNull filter.Address || not (filter.Address |> Array.exists (fun address -> String.Equals(address, contract.Address, StringComparison.OrdinalIgnoreCase))) then invalidArg "filter" "Filter must include this contract address"
    task {
        let! logs = contract.Eth.Filters.GetLogs.SendRequestAsync(filter)
        let result = ResizeArray<EventLog<AccountGrantAssignedEvent>>()
        let event = contract.GetEventBySignature("0x8069a87735a71ef98bd747a24e1502aeda0a0b31aef75137cb7b07fbc97716a4")
        for log in logs do
            if String.Equals(log.Address, contract.Address, StringComparison.OrdinalIgnoreCase) && event.IsLogForEvent(log) then
                result.Add(EventLog<AccountGrantAssignedEvent>(decodeAccountGrantAssignedEvent contract log, log))
        return result
    }

